cd /tmp
perl -e '
sub run {
  my ($label, $w) = @_;
  my ($out, $err);
  my $pid = open(my $oh, "-|");
  die unless defined $pid;
  if ($pid == 0) { open(STDERR, ">", "/tmp/perr.txt"); exec("/workspace/dataset/test13_executable", $w) or exit 127; }
  local $/; $out = <$oh>; $out = "" unless defined $out; close($oh); my $rc = $?;
  open(my $eh, "<", "/tmp/perr.txt"); local $/; $err = <$eh>; $err="" unless defined $err; close($eh);
  printf("%-28s rc=%-3d sig=%-2d outlen=%-6d nl=%-3d errlen=%d\n", $label, $rc>>8, $rc & 127, length($out), ($out =~ tr/\n//), length($err));
  return $out;
}
run("high_byte_0xFF", "\xff");
run("high_bytes_80_9F", "\x80\x9f\xa0\xfe");
run("utf8_cafe", "caf\xc3\xa9");
