cd /tmp
perl -e '
# brute-force: many random args, assert exactly 13 newlines, rc 0, empty stderr
my @chars = map { chr($_) } (1..255);
my $bad = 0; my $n = 0;
for my $trial (1..120) {
  my $len = 1 + int(rand(12));
  my $w = "";
  for (1..$len) { my $c = $chars[int(rand(scalar @chars))]; redo if $c eq "\n"; $w .= $c; }
  next if $w =~ /\n/;
  my $pid = open(my $oh, "-|");
  if ($pid == 0) { open(STDERR, ">", "/tmp/be.txt"); exec("/workspace/dataset/test13_executable", $w) or exit 127; }
  local $/; my $o = <$oh>; $o = "" unless defined $o; close($oh); my $rc = $?;
  my $nl = ($o =~ tr/\n//);
  my $es = -s "/tmp/be.txt";
  $n++;
  if ($nl != 13 || ($rc>>8) != 0 || ($rc & 127) != 0 || $es != 0 || $o !~ /\n$/) {
    $bad++;
    my $h = unpack("H*", $w);
    printf("BAD w_hex=%s nl=%d rc=%d sig=%d errsz=%d\n", $h, $nl, $rc>>8, $rc&127, $es);
  }
}
print "trials=$n bad=$bad\n";
'

