echo "=== streaming check: is child still alive after first bytes arrive? ==="
perl -e '
my $w = "z" x 131071;
my $pid = open(my $oh, "-|", "/workspace/dataset/test13_executable", $w) or die $!;
my $buf; read($oh, $buf, 64);
my $alive = kill(0, $pid) ? 1 : 0;
print "got_bytes=", length($buf), " child_alive_after_first_read=$alive\n";
# drain
local $/; my $rest = <$oh>; close($oh);
print "total=", 64 + length($rest), " rc=", $?>>8, "\n";
'

cd /tmp
perl -e '
use POSIX;
pipe(my $r, my $w) or die;
my $pid = fork(); die unless defined $pid;
if ($pid == 0) { close($r); open(STDOUT, ">&", $w) or die; exec("/workspace/dataset/test13_executable", "cat"); exit 127; }
close($w);
my @chunks;
while (1) { my $b; my $n = sysread($r, $b, 65536); last unless $n; push @chunks, $b; }
close($r); waitpid($pid,0);
print "num_sysread_chunks=", scalar(@chunks), "\n";
for my $i (0..$#chunks) { my $c = $chunks[$i]; $c =~ s/\n/\\n/g; printf("  chunk%02d len=%-3d [%s]\n", $i, length($chunks[$i]), $c); }
'

