input.command:
cd /tmp
echo "=== repeat chunk-alignment test x6 ==="
perl -e '
for my $t (1..6) {
  pipe(my $r, my $w) or die;
  my $pid = fork(); die unless defined $pid;
  if ($pid == 0) { close($r); open(STDOUT, ">&", $w) or die; exec("/workspace/dataset/test13_executable", "cat"); exit 127; }
  close($w);
  my @c; while (1) { my $b; my $n = sysread($r, $b, 65536); last unless $n; push @c, $b; }
  close($r); waitpid($pid,0);
  my $allnl = 1; for (@c) { $allnl = 0 unless /\n$/ }
  my $lens = join(",", map { length } @c);
  print "trial$t chunks=", scalar(@c), " every_chunk_ends_with_LF=$allnl lens=[$lens]\n";
}
'

cd /tmp
echo "=== exact tail bytes for several args ==="
for a in cat '' x 'Foo'; do printf 'arg=[%s] tail6: ' "$a"; /workspace/dataset/test13_executable "$a" | tail -c 6 | od -An -c | tr -s ' '; done
echo "=== cwd independence ==="
mkdir -p /tmp/dirA /tmp/dirB
( cd /tmp/dirA && /workspace/dataset/test13_executable cat ) > /tmp/A.out
( cd / && /workspace/dataset/test13_executable cat ) > /tmp/B.out
cmp /tmp/A.out /tmp/B.out && echo "cwd_independent"
echo "=== 250 random printable-ASCII args: rc/nl/stderr invariants ==="
perl -e '
my $bad=0; my $n=0;
for (1..250) {
  my $len = 1 + int(rand(10));
  my $w = join("", map { chr(32 + int(rand(95))) } 1..$len);
  my $pid = open(my $oh, "-|");
  if ($pid==0) { open(STDERR,">","/tmp/bb.txt"); exec("/workspace/dataset/test13_executable",$w) or exit 127; }
  local $/; my $o=<$oh>; $o="" unless defined $o; close($oh); my $rc=$?;
  $n++;
  my $nl=($o=~tr/\n//); my $es=-s "/tmp/bb.txt";
  if ($nl!=13 || ($rc>>8)!=0 || ($rc&127)!=0 || $es!=0 || $o!~/\n$/ || $o=~/\n\n$/ && $w!~/^\s*$/) {
    # note: \n\n at end is legitimate when line13 is empty; only flag structural problems
    if ($nl!=13 || ($rc>>8)!=0 || ($rc&127)!=0 || $es!=0 || $o!~/\n$/) { $bad++; printf("BAD hex=%s nl=%d rc=%d errsz=%d\n", unpack("H*",$w), $nl, $rc>>8, $es); }
  }
}
print "trials=$n structural_failures=$bad\n";
'
